from pathlib import Path
import json, base64, re, argparse
root=Path(__file__).resolve().parents[2]
source=(root/'releases/1.30.1/mvu.mjs').read_text()
initial=json.loads(re.search(r'const ShrineInitial = (.*);',source)[1])
module=(Path(__file__).parent/'scene.mjs').read_text().replace('export ','')
def data(p): return 'data:image/webp;base64,'+base64.b64encode(p.read_bytes()).decode()
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>御影神社 · 模块建设小样</title><style>
@font-face{font-family:Shrine;src:url(__FONT__) format('woff2');font-display:swap}*{box-sizing:border-box}body{margin:0;background:#ece6d8;color:#433e34;font-family:Shrine,system-ui,sans-serif}main{max-width:980px;margin:26px auto;padding:0 18px}header{display:flex;justify-content:space-between;align-items:end;gap:12px;margin-bottom:16px}h1{font-family:Shrine,serif;font-size:28px;font-weight:500;letter-spacing:4px;margin:5px 0}small{color:#746f60;font-size:12px;letter-spacing:2px}.tag{border:1px solid #bcb49e;border-radius:20px;padding:7px 12px;font-size:12px}.board{position:relative;border:8px solid #6b5b46;box-shadow:0 8px 25px #4d493c28;background:#819370;border-radius:5px;overflow:hidden}canvas{display:block;width:100%;height:auto;image-rendering:pixelated}.plaque{position:absolute;top:12px;left:12px;color:#f6ecd6;background:#4a5042e6;padding:8px 14px;border:1px solid #c5bb91;font-family:Shrine,serif;letter-spacing:3px}.period{position:absolute;right:12px;top:12px;border:1px solid #c7c19f;background:#f3eddbde;padding:7px 12px;border-radius:20px;font-size:12px}button,select,.file{font:inherit;color:inherit}button,.file{background:#f7f1e4;border:1px solid #bcb29d;padding:10px 15px;border-radius:5px;cursor:pointer}button:hover,.file:hover{background:#fffaf0}button:focus-visible,select:focus-visible,.file:focus-within{outline:3px solid #b16b50;outline-offset:2px}.facilities{display:grid;grid-template-columns:repeat(5,1fr);gap:9px;margin:17px 0}.facility{background:#f7f2e8;border:1px solid #c6bdab;border-radius:5px;padding:12px;text-align:left}.facility strong{display:block;font-family:Shrine,serif;font-size:20px;margin-bottom:7px}.facility span{font-size:12px;color:#827767}.facility.done{border-color:#738565;background:#e3e9d9}.facility.done span{color:#4e6843}.note{min-height:57px;padding:15px 17px;background:#e5ddca;border-left:3px solid #927252;font-size:14px;line-height:1.8}.toolbar{display:flex;gap:8px;flex-wrap:wrap;margin:15px 0}.toolbar button,.file{font-size:13px}.file input{position:absolute;width:1px;height:1px;opacity:0}details{border-top:1px solid #c5bdab;margin-top:18px;padding-top:15px;font-size:13px}summary{cursor:pointer}p{line-height:1.8}label.field{display:inline-flex;gap:6px;align-items:center;margin:12px 12px 0 0}select{background:#f7f2e8;border:1px solid #b9ae98;border-radius:3px;padding:6px}.foot{font-size:12px;color:#807967;line-height:1.8;margin:14px 0}.flash{animation:flash .8s ease-out}@keyframes flash{from{filter:brightness(1.15)}to{filter:brightness(1)}}@media(prefers-reduced-motion:reduce){.flash{animation:none}}@media(max-width:550px){main{margin:16px auto;padding:0 10px}header{align-items:start}h1{font-size:22px}.tag{max-width:95px;line-height:1.5;text-align:center}.board{border-width:5px}.facilities{gap:5px}.facility{padding:10px 4px;text-align:center}.facility strong{font-size:16px}.facility span{font-size:10px}.plaque{font-size:11px;padding:5px 8px;top:7px;left:7px}.period{top:7px;right:7px;padding:4px 7px;font-size:10px}}
</style><main><header><div><small>MIKAGE · MODULAR GARDEN</small><h1>一座慢慢长大的神社</h1></div><span class="tag">画面接轨小样<br>不写入存档</span></header><div class="board"><canvas id="scene" role="img"></canvas><div class="plaque">御影神社</div><button class="period" id="period">白昼 · 切换时段</button></div><div class="facilities" id="facilities"></div><div class="note" role="status" aria-live="polite" id="feedback">点击任意设施，查看完工后留下的变化。其他设施与生活陈设会留在原位。</div><div class="toolbar"><button id="sequence">依次完工</button><button id="reset">恢复旧版初始状态</button><button id="empty">空场拼装</button><label class="file">导入旧状态 JSON<input id="import" type="file" accept=".json,application/json"></label></div><details><summary>查看原有修缮进度与接轨说明</summary><div id="stages"></div><p>0 为尚未修复；1～3 沿用原有外观；4 显示完工建筑与附属部件。这里没有把修缮过程当成新的建筑等级。</p><p>建设任务、材料消耗、章节解锁仍由原系统处理。本页只演示已有状态如何改变画面，所有按钮只改变本页副本。原来的风铃、坐垫、灯笼按保存的槽位显示。</p></details><p class="foot" id="foot">部件独立叠加 · 固定场地 · 兼容原五项设施 · 旧版初始状态</p></main><script>
__MODULE__
const initial=__INITIAL__;
let state=structuredClone(initial),listeners=new Set(),generation=0,imported=false;
const feedback=document.querySelector('#feedback');
const controllerPromise=mount(document.querySelector('canvas'),{getState:()=>state,subscribe:cb=>{listeners.add(cb);return()=>listeners.delete(cb)},atlasURL:__ATLAS__,decorURL:__DECOR__,onRender:view=>{
 const group=document.querySelector('#facilities');group.replaceChildren();
 for(const name of facilities){const n=view.stages[name],b=document.createElement('button');b.className='facility'+(n===4?' done':'');b.dataset.facility=name;b.setAttribute('aria-pressed',String(n===4));const strong=document.createElement('strong');strong.textContent=name;const span=document.createElement('span');span.textContent=n===4?'✓ 已完工':n===0?'＋ 添加模块':'查看完工';b.append(strong,span);b.onclick=()=>{generation++;state.神社[name]=n===0?1:n===4?1:4;sync(state.神社[name]===4?changes[name]:state.神社[name]===0?'移除部件。':'已显示'+name+'原有外观。')};group.append(b)}
 document.querySelector('#period').textContent=view.period+' · 切换时段';
}});
function sync(message){for(const cb of listeners)cb(state);feedback.textContent=message;document.querySelector('#foot').textContent='部件独立叠加 · 已完工 '+facilities.filter(n=>state.神社[n]===4).length+'/5 · '+(imported?'旧状态副本':'演示状态副本');document.querySelector('.board').classList.remove('flash');void document.querySelector('.board').offsetWidth;document.querySelector('.board').classList.add('flash');for(const s of document.querySelectorAll('[data-stage]'))s.value=state.神社[s.dataset.stage]??1;}
for(const name of facilities){const label=document.createElement('label');label.className='field';label.append(name);const s=document.createElement('select');s.dataset.stage=name;s.setAttribute('aria-label',name+'修缮进度');for(let n=0;n<=4;n++){const o=new Option(n+' · '+['尚未修复','待整修','备料中','施工中','已完工'][n],n);s.add(o)}s.value=state.神社[name];s.onchange=()=>{generation++;state.神社[name]=Number(s.value);sync('读取'+name+'修缮进度 '+s.value+'，材料与其他字段保持原值。')};label.append(s);document.querySelector('#stages').append(label)}
document.querySelector('#reset').onclick=()=>{generation++;imported=false;state=structuredClone(initial);sync('已恢复原版初始状态。风铃、坐垫、未点亮的灯笼仍在。')};
document.querySelector('#empty').onclick=()=>{generation++;state=structuredClone(initial);for(const n of facilities)state.神社[n]=0;state.生活.布置=[];imported=false;sync('空场拼装：先点击设施添加基础模块，再点一次查看完工外观。')};
document.querySelector('#sequence').onclick=async()=>{const g=++generation;for(const name of facilities){if(g!==generation)return;state.神社[name]=4;sync(changes[name]);await new Promise(r=>setTimeout(r,1200))}};
document.querySelector('#period').onclick=()=>{const times=['白昼','傍晚','夜晚'];state.环境??={};state.环境.时段=times[(times.indexOf(state.环境.时段)+1)%3];sync('仅切换观看时段，不推进剧情时间。')};
document.querySelector('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>10*1024*1024)throw Error('请选择 10 MB 以内的状态 JSON。');const candidate=structuredClone(unwrap(JSON.parse(await file.text())));project(candidate);generation++;state=candidate;imported=true;sync('已读取旧状态副本；原存档没有修改。')}catch(err){feedback.textContent=err.message}finally{e.target.value=''}};
window.preview={ready:controllerPromise,read:()=>structuredClone(state),load:value=>{const candidate=structuredClone(unwrap(value));project(candidate);generation++;state=candidate;imported=true;sync('已读取旧状态副本。')},inspect:async()=> (await controllerPromise).inspect(),dispose:async()=>{generation++;(await controllerPromise).dispose()}};
controllerPromise.catch(error=>feedback.textContent=error.message);
</script></html>'''
html=html.replace('__MODULE__',module).replace('__INITIAL__',json.dumps(initial,ensure_ascii=False)).replace('__ATLAS__',json.dumps(data(root/'assets/ui/shrine-modular-v1.webp'))).replace('__DECOR__',json.dumps(data(root/'assets/ui/life-v147-objects.webp')))
html=html.replace('__FONT__', 'data:font/woff2;base64,'+base64.b64encode((root/'assets/ui/shrine-serif-v145.woff2').read_bytes()).decode())
p=argparse.ArgumentParser();p.add_argument('--output',type=Path,default=Path(__file__).parent/'preview.html');args=p.parse_args()
out=args.output;out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(html)
print(out, out.stat().st_size)
